const uiMonthsBN=['জানুয়ারি','ফেব্রুয়ারি','মার্চ','এপ্রিল','মে','জুন','জুলাই','আগস্ট','সেপ্টেম্বর','অক্টোবর','নভেম্বর','ডিসেম্বর'],uiMonthsEN=['January','February','March','April','May','June','July','August','September','October','November','December'];
function normalizeUILocale(text){if(uiLanguage==='en'){let value=text.replace(/[০-৯]/g,d=>'০১২৩৪৫৬৭৮৯'.indexOf(d)).replace(/এএম/g,'AM').replace(/পিএম/g,'PM');uiMonthsBN.forEach((month,index)=>{value=value.replaceAll(month,uiMonthsEN[index])});value=value.replaceAll('জানুয়ারি','January').replaceAll('ফেব্রুয়ারি','February');return value}let value=text;uiMonthsEN.forEach((month,index)=>{value=value.replaceAll(month,uiMonthsBN[index])});if(/[৳$€£]|^\d{4}-|^\d{1,2}:\d{2}|AM|PM|টি |^\d{4}$/.test(value))value=value.replace(/\d/g,d=>'০১২৩৪৫৬৭৮৯'[Number(d)]).replace(/AM/g,'এএম').replace(/PM/g,'পিএম');return value}
function translateUI(text){return normalizeUILocale(translateUIRaw(text))}
function translateUIRaw(text){if(uiLanguage!=='en')return text;const trimmed=text.trim();if(uiWords[trimmed])return text.replace(trimmed,uiWords[trimmed]);const digits=s=>s.replace(/[০-৯]/g,d=>'০১২৩৪৫৬৭৮৯'.indexOf(d));if(/^[৳$€£]\s*[০-৯\d,.]+$/.test(trimmed))return digits(text);let match;if((match=/^([০-৯\d]+)টি (লেনদেন|খরচ)$/.exec(trimmed)))return digits(match[1])+' '+(match[2]==='খরচ'?(Number(digits(match[1]))===1?'expense':'expenses'):(Number(digits(match[1]))===1?'transaction':'transactions'));if((match=/^(নির্বাচিত মাস|নির্বাচিত বছর|নির্বাচিত দিন|তারিখ|মোবাইল)([: ·]+)(.*)$/.exec(trimmed)))return ({'নির্বাচিত মাস':'Selected month','নির্বাচিত বছর':'Selected year','নির্বাচিত দিন':'Selected date','তারিখ':'Date','মোবাইল':'Mobile'}[match[1]])+match[2]+match[3].replace('এই দিনের হিসাব','Totals for this day');if(trimmed.startsWith('গত মাস · '))return text.replace('গত মাস · ','Last month · ');return text}
(() => {
 const remembered=new WeakMap(),attributeSources=new WeakMap();
 function apply(){document.documentElement.lang=uiLanguage;const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let node;while((node=walker.nextNode())){if(node.parentElement.closest('script,style,textarea,[data-user-text],.profile-name,.person-detail-name,.expense-history-description,.entry-description,.profile-settings-person strong'))continue;const record=remembered.get(node),source=record&&node.nodeValue===record.output?record.source:node.nodeValue,output=translateUI(source);remembered.set(node,{source,output});if(node.nodeValue!==output)node.nodeValue=output}document.querySelectorAll('[placeholder],[aria-label],[title]').forEach(element=>{const records=attributeSources.get(element)||{};for(const key of ['placeholder','aria-label','title'])if(element.hasAttribute(key)){const value=element.getAttribute(key),record=records[key],source=record&&value===record.output?record.source:value,output=translateUI(source);records[key]={source,output};if(value!==output)element.setAttribute(key,output)}attributeSources.set(element,records)});const select=document.querySelector('#language-switch');if(select)select.value=uiLanguage}
 window.setUILanguage=language=>{uiLanguage=language==='bn'?'bn':'en';try{localStorage.setItem('dailytally-language',uiLanguage)}catch{}apply()};const select=document.querySelector('#language-switch');if(select)select.onchange=event=>window.setUILanguage(event.target.value);
 let scheduled=false;new MutationObserver(()=>{if(scheduled)return;scheduled=true;queueMicrotask(()=>{scheduled=false;apply()})}).observe(document.body,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:['placeholder','aria-label','title']});
 const nativeAlert=window.alert,nativeConfirm=window.confirm;window.alert=message=>nativeAlert.call(window,translateUI(String(message)));window.confirm=message=>nativeConfirm.call(window,translateUI(String(message)));apply();
})();
